package base

import (
	"strings"
)

type Field struct {
	bson string
	typ  string
}

func NewField(name, typ string) Field {
	return Field{name, typ}
}

func (f Field) Type() string {
	return f.typ
}

func (f Field) String() string {
	return f.bson
}

var (
	IdField = NewField("_id", "bson.ObjectId")
)

type Dir int

const (
	Asc  Dir = 1
	Desc Dir = -1
)

type Sort []FieldSort

type FieldSort struct {
	F Field
	D Dir
}

func (s Sort) String() string {
	var fields []string
	for _, fs := range s {
		f := ""
		if fs.D == Desc {
			f += "-"
		}

		f += fs.F.String()

		fields = append(fields, f)
	}

	return strings.Join(fields, ",")
}

func (s Sort) IsEmpty() bool {
	return len(s) == 0
}

package operators

import (
	"testing"

	"github.com/tyba/storable"

	"gopkg.in/check.v1"
	"gopkg.in/mgo.v2/bson"
)

var (
	Foo = storable.NewField("foo", "")
)

func Test(t *testing.T) { check.TestingT(t) }

type OperatorsSuite struct{}

var _ = check.Suite(&OperatorsSuite{})

func (s *OperatorsSuite) TestLogical(c *check.C) {
	or := Or(bson.M{"foo": "qux"}, bson.M{"qux": "qux"})
	c.Assert(or, check.DeepEquals, bson.M{
		"$or": []bson.M{
			bson.M{"foo": "qux"},
			bson.M{"qux": "qux"},
		},
	})

	and := And(bson.M{"foo": "qux"}, bson.M{"qux": "qux"})
	c.Assert(and, check.DeepEquals, bson.M{
		"$and": []bson.M{
			bson.M{"foo": "qux"},
			bson.M{"qux": "qux"},
		},
	})

	not := Not(bson.M{"foo": "qux"})
	c.Assert(not, check.DeepEquals, bson.M{"foo": bson.M{"$not": "qux"}})

	nor := Nor(bson.M{"foo": "qux"}, bson.M{"qux": "qux"})
	c.Assert(nor, check.DeepEquals, bson.M{
		"$nor": []bson.M{
			bson.M{"foo": "qux"},
			bson.M{"qux": "qux"},
		},
	})
}

func (s *OperatorsSuite) TestComparsion(c *check.C) {
	eq := Eq(Foo, "bar")
	c.Assert(eq, check.DeepEquals, bson.M{"foo": bson.M{"$eq": "bar"}})

	gt := Gt(Foo, "bar")
	c.Assert(gt, check.DeepEquals, bson.M{"foo": bson.M{"$gt": "bar"}})

	gte := Gte(Foo, "bar")
	c.Assert(gte, check.DeepEquals, bson.M{"foo": bson.M{"$gte": "bar"}})

	lt := Lt(Foo, "bar")
	c.Assert(lt, check.DeepEquals, bson.M{"foo": bson.M{"$lt": "bar"}})

	lte := Lte(Foo, "bar")
	c.Assert(lte, check.DeepEquals, bson.M{"foo": bson.M{"$lte": "bar"}})

	ne := Ne(Foo, "bar")
	c.Assert(ne, check.DeepEquals, bson.M{"foo": bson.M{"$ne": "bar"}})

	in := In(Foo, "bar", "qux")
	c.Assert(in, check.DeepEquals, bson.M{"foo": bson.M{"$in": []interface{}{"bar", "qux"}}})

	nin := Nin(Foo, "bar", "qux")
	c.Assert(nin, check.DeepEquals, bson.M{"foo": bson.M{"$nin": []interface{}{"bar", "qux"}}})
}

func (s *OperatorsSuite) TestElement(c *check.C) {
	exists := Exists(Foo, true)
	c.Assert(exists, check.DeepEquals, bson.M{"foo": bson.M{"$exists": true}})

	t := Type(Foo, Double)
	c.Assert(t, check.DeepEquals, bson.M{"foo": bson.M{"$type": Double}})
}

func (s *OperatorsSuite) TestEvaluation(c *check.C) {
	mod := Mod(Foo, 42, 82)
	c.Assert(mod, check.DeepEquals, bson.M{"foo": bson.M{"$mod": []float64{42, 82}}})

	re := RegEx(Foo, ".*", "i")
	c.Assert(re, check.DeepEquals, bson.M{
		"foo": bson.M{"$regex": bson.RegEx{Pattern: ".*", Options: "i"}},
	})

	text := Text(Foo, "foo", "none")
	c.Assert(text, check.DeepEquals, bson.M{
		"foo": bson.M{"$text": bson.M{"$search": "foo", "$language": "none"}},
	})

	where := Where(Foo, "foo", nil)
	c.Assert(where, check.DeepEquals, bson.M{
		"foo": bson.M{"$where": bson.JavaScript{Code: "foo", Scope: interface{}(nil)}},
	})
}

func (s *OperatorsSuite) TestArray(c *check.C) {
	all := All(Foo, "qux", "bar")
	c.Assert(all, check.DeepEquals, bson.M{"foo": bson.M{"$all": []interface{}{"qux", "bar"}}})

	size := Size(Foo, 2)
	c.Assert(size, check.DeepEquals, bson.M{"foo": bson.M{"$size": 2}})
}

func (s *OperatorsSuite) TestComment(c *check.C) {
	comment := Comment("foo")
	c.Assert(comment, check.DeepEquals, bson.M{"$comment": "foo"})
}

package storable

import (
	"errors"

	"gopkg.in/mgo.v2"
	"gopkg.in/mgo.v2/bson"
)

var (
	NonNewDocumentErr  = errors.New("Cannot insert a non new document.")
	NewDocumentErr     = errors.New("Cannot updated a new document.")
	EmptyQueryInRawErr = errors.New("Empty queries are not allowed on raw ops.")
	EmptyIdErr         = errors.New("A document without id is not allowed.")
)

type Store struct {
	db         *mgo.Database
	collection string
}

// NewStore returns a new Store instance
func NewStore(db *mgo.Database, collection string) *Store {
	return &Store{
		db:         db,
		collection: collection,
	}
}

// Insert insert the given document in the collection, returns error if no-new
// document is given. The document id is setted if is empty.
func (s *Store) Insert(doc DocumentBase) error {
	if !doc.IsNew() {
		return NonNewDocumentErr
	}

	if len(doc.GetId()) == 0 {
		doc.SetId(bson.NewObjectId())
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	err := c.Insert(doc)
	if err == nil {
		doc.SetIsNew(false)
	}

	return err
}

// Update update the given document in the collection, returns error if a new
// document is given.
func (s *Store) Update(doc DocumentBase) error {
	if doc.IsNew() {
		return NewDocumentErr
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	return c.UpdateId(doc.GetId(), doc)
}

// Save insert or update the given document in the collection, a document with
// id should be provided. Upsert is used (http://godoc.org/gopkg.in/mgo.v2#Collection.Upsert)
func (s *Store) Save(doc DocumentBase) (inserted bool, err error) {
	id := doc.GetId()
	if len(id) == 0 {
		return false, EmptyIdErr
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	inf, err := c.UpsertId(id, doc)
	if err != nil {
		return false, err
	}

	doc.SetIsNew(false)
	return inf.Updated > 0, nil
}

// Delete remove the document from the collection
func (s *Store) Delete(doc DocumentBase) error {
	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	return c.RemoveId(doc.GetId())
}

// Find executes the given query in the collection
func (s *Store) Find(q Query) (*ResultSet, error) {
	sess, c := s.getSessionAndCollection()
	mq := c.Find(q.GetCriteria())

	if !q.GetSort().IsEmpty() {
		mq.Sort(q.GetSort().String())
	}

	if q.GetSkip() != 0 {
		mq.Skip(q.GetSkip())
	}

	if q.GetLimit() != 0 {
		mq.Limit(q.GetLimit())
	}

	return &ResultSet{session: sess, mgoQuery: mq}, nil
}

// RawUpdate performes a direct update in the collection, update is wrapped on
// a $set operator. If a query without criteria is given EmptyQueryInRawErr is
// returned
func (s *Store) RawUpdate(query Query, update interface{}, multi bool) error {
	criteria := query.GetCriteria()
	if len(criteria) == 0 {
		return EmptyQueryInRawErr
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	var err error
	if multi {
		_, err = c.UpdateAll(criteria, bson.M{"$set": update})
	} else {
		err = c.Update(criteria, bson.M{"$set": update})
	}

	return err
}

// RawDelete performes a direct remove in the collection. If a query without
// criteria is given EmptyQueryInRawErr is returned
func (s *Store) RawDelete(query Query, multi bool) error {
	criteria := query.GetCriteria()
	if len(criteria) == 0 {
		return EmptyQueryInRawErr
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	var err error
	if multi {
		_, err = c.RemoveAll(criteria)
	} else {
		err = c.Remove(criteria)
	}

	return err
}

func (s *Store) getSessionAndCollection() (*mgo.Session, *mgo.Collection) {
	sess := s.db.Session.Clone()

	return sess, sess.DB(s.db.Name).C(s.collection)
}

