package storable

import (
	"errors"

	"gopkg.in/mgo.v2"
	"gopkg.in/mgo.v2/bson"
)

var (
	NonNewDocumentErr = errors.New("Cannot insert a non new document.")
	NewDocumentErr    = errors.New("Cannot updated a new document.")
)

type Store struct {
	Collection string

	collection *mgo.Collection
}

func NewStore(db *mgo.Database, collection string) *Store {
	return &Store{
		Collection: collection,
		collection: db.C(collection),
	}
}

func (s *Store) Insert(doc DocumentBase) error {
	if !doc.IsNew() {
		return NonNewDocumentErr
	}

	doc.SetId(bson.NewObjectId())
	err := s.collection.Insert(doc)
	if err == nil {
		doc.SetIsNew(false)
	}

	return err
}

func (s *Store) Update(doc DocumentBase) error {
	if doc.IsNew() {
		return NewDocumentErr
	}

	return s.collection.Update(bson.M{"_id": doc.GetId()}, doc)
}

func (s *Store) Delete(doc DocumentBase) error {
	return s.collection.Remove(bson.M{"_id": doc.GetId()})
}

func (s *Store) Find(q Query) (*ResultSet, error) {
	mq := s.collection.Find(q.GetCriteria())

	if !q.GetSort().IsEmpty() {
		mq.Sort(q.GetSort().String())
	}

	if q.GetSkip() != 0 {
		mq.Skip(q.GetSkip())
	}

	if q.GetLimit() != 0 {
		mq.Limit(q.GetLimit())
	}

	return &ResultSet{mgoQuery: mq}, nil
}

func (s *Store) RawUpdate(query Query, update interface{}) error {
	return s.collection.Update(query.GetCriteria(), update)
}

package operators

import (
	"gopkg.in/mgo.v2/bson"
)

// Eq Matches values that are equal to a specified value.
func Eq(field Field, value interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$eq": value}}
}

// Gt Matches values that are greater than a specified value.
func Gt(field Field, value interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$gt": value}}
}

// Gte Matches values that are greater than or equal to a specified value.
func Gte(field Field, value interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$gte": value}}
}

// Lt Matches values that are less than a specified value.
func Lt(field Field, value interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$lt": value}}
}

// Lte Matches values that are less than or equal to a specified value.
func Lte(field Field, value interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$lte": value}}
}

// Ne Matches all values that are not equal to a specified value.
func Ne(field Field, value interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$ne": value}}
}

// In Matches any of the values.
func In(field Field, values ...interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$in": values}}
}

// Nin Matches none of the values.
func Nin(field Field, values ...interface{}) bson.M {
	return bson.M{field.String(): bson.M{"$nin": values}}
}

