func (c *CmdGenerate) Execute(args []string) error {
	if !isDirectory(c.Input) {
		return fmt.Errorf("Input path should be a directory %s", c.Input)
	}

	p := mongogen.NewProcessor(c.Input, []string{c.Output})
	name, models, err := p.Do()
