package generator

import (
	"bytes"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"reflect"
	"strconv"

	. "github.com/tyba/mongogen/model"
)

type Processor struct {
	filename string
	fileset  *token.FileSet
	file     *ast.File
	Models   []*Model
}

func NewProcessor(filename string) *Processor {
	return &Processor{
		filename: filename,
		fileset:  token.NewFileSet(),
		Models:   make([]*Model, 0),
	}
}

func (p *Processor) Filename() string {
    return p.filename
}

func (p *Processor) Process() error {
	err := p.parseFile()
	if err == nil {
		p.extractModels()
	}

	return err
}

func (p *Processor) Package() string {
	return p.file.Name.Name
}

func (p *Processor) parseFile() error {
	var err error
	p.file, err = parser.ParseFile(
		p.fileset, p.filename, nil, parser.ParseComments|parser.Trace,
	)

	return err
}

func (p *Processor) extractModels() []*Model {
	for _, decl := range p.file.Decls {
		ast.Walk(p, decl)
	}

	return make([]*Model, 0)
}

func (p *Processor) Visit(node ast.Node) ast.Visitor {
	switch node := node.(type) {
	case *ast.GenDecl:
		if node.Tok == token.TYPE {
			p.processTypeDecl(node)
		}
	}

	return p
}

func (p *Processor) processTypeDecl(td *ast.GenDecl) {
	for _, spec := range td.Specs {
		ts := spec.(*ast.TypeSpec)
		if st, ok := ts.Type.(*ast.StructType); ok {
			name := ts.Name.Name
			p.processStruct(name, st)
		}
	}
}

func (p *Processor) processStruct(name string, st *ast.StructType) {

	sp := newStructProcessor(p)
	model := sp.process(name, st)
	if model != nil {
		p.Models = append(p.Models, model)
	}
}

type structProcessor struct {
	processor *Processor
	generate  bool
	Model     *Model
}

func newStructProcessor(p *Processor) *structProcessor {
	return &structProcessor{
		processor: p,
		generate:  false,
		Model:     nil,
	}
}

func (sp *structProcessor) process(name string, st *ast.StructType) *Model {
	fields := make([]Field, 0)
	for _, fieldDef := range st.Fields.List {
		more := sp.processFieldDef(fieldDef)
		fields = append(fields, more...)
	}

	if sp.generate {
		return &Model{
			Name:   name,
			Fields: fields,
		}
	}

	return nil
}

func (sp *structProcessor) processFieldDef(def *ast.Field) []Field {

	typeStr := sp.processor.nodeString(def.Type)
	structTag := sp.extractTag(def)
	if structTag != nil && structTag.Get("collection") != "" {
		sp.generate = true
	}

	fields := sp.makeFields(def.Names, typeStr, structTag)

	return fields
}

func (sp *structProcessor) makeFields(
	names []*ast.Ident,
	typeStr string,
	tag *reflect.StructTag) []Field {

	fields := make([]Field, 0)
	for _, ident := range names {
		field := Field{
			Name: sp.processor.nodeString(ident),
			Type: typeStr,
			Tag:  tag,
		}
		fields = append(fields, field)

	}
	return fields
}

func (sp *structProcessor) extractTag(f *ast.Field) *reflect.StructTag {
	tag := f.Tag
	if tag != nil {
		if tagStr, err := strconv.Unquote(tag.Value); err == nil {
			st := reflect.StructTag(tagStr)
			return &st
		}
	}

	return nil
}

func (p *Processor) nodeString(n ast.Node) string {
	var buf bytes.Buffer
	printer.Fprint(&buf, p.fileset, n)
	return buf.String()
}

package generator

import (
	"fmt"
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"io/ioutil"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"

	_ "golang.org/x/tools/go/gcimporter"
	"golang.org/x/tools/go/types"
)

const BaseDocument = "gopkg.in/src-d/storable.v1.Document"

type Processor struct {
	Path       string
	Ignore     map[string]bool
	TypesPkg   *types.Package
	SourceCode map[string][]byte
}

func NewProcessor(path string, ignore []string) *Processor {
	i := make(map[string]bool, 0)
	for _, file := range ignore {
		i[file] = true
	}

	return &Processor{
		Path:   path,
		Ignore: i,
	}
}

func (p *Processor) Do() (*Package, error) {
	files, err := p.getSourceFiles()
	if err != nil {
		return nil, err
	}

	p.SourceCode, err = p.readSourceFiles(files)
	if err != nil {
		return nil, err
	}

	p.TypesPkg, _ = p.parseSourceFiles(files)
	return p.processTypesPkg()
}

func (p *Processor) getSourceFiles() ([]string, error) {
	pkg, err := build.Default.ImportDir(p.Path, 0)
	if err != nil {
		return nil, fmt.Errorf("cannot process directory %s: %s", p.Path, err)
	}

	var files []string
	files = append(files, pkg.GoFiles...)
	files = append(files, pkg.CgoFiles...)

	if len(files) == 0 {
		return nil, fmt.Errorf("%s: no buildable Go files", p.Path)
	}

	return joinDirectory(p.Path, p.removeIngoredFiles(files)), nil
}

func (p *Processor) removeIngoredFiles(filenames []string) []string {
	var output []string
	for _, filename := range filenames {
		if _, ok := p.Ignore[filename]; ok {
			continue
		}

		output = append(output, filename)
	}

	return output
}

func (p *Processor) readSourceFiles(filenames []string) (map[string][]byte, error) {
	source := make(map[string][]byte, 0)
	for _, filename := range filenames {
		b, err := ioutil.ReadFile(filename)
		if err != nil {
			return source, err
		}

		source[filename] = b
	}

	return source, nil
}

func (p *Processor) parseSourceFiles(filenames []string) (*types.Package, error) {
	var files []*ast.File
	fs := token.NewFileSet()
	for _, filename := range filenames {
		file, err := parser.ParseFile(fs, filename, nil, 0)
		if err != nil {
			return nil, fmt.Errorf("parsing package: %s: %s", filename, err)
		}

		files = append(files, file)
	}

	config := types.Config{FakeImportC: true, Error: func(error) {}}
	info := &types.Info{}

	return config.Check(p.Path, fs, files, info)
}

func (p *Processor) processTypesPkg() (*Package, error) {
	pkg := &Package{Name: p.TypesPkg.Name()}
	p.processPackage(pkg)

	return pkg, nil
}

func (p *Processor) processPackage(pkg *Package) {
	var newFuncs []*types.Func

	fmt.Println("Package: ", pkg.Name)
	s := p.TypesPkg.Scope()
	for _, name := range s.Names() {
		fun := p.tryGetFunction(s.Lookup(name))
		if fun != nil {
			pkg.Functions = append(pkg.Functions, name)
			if strings.HasPrefix(fun.Name(), "new") {
				newFuncs = append(newFuncs, fun)
			}
		}

		str := p.tryGetStruct(s.Lookup(name).Type())
		if str == nil {
			continue
		}

		if m := p.processStruct(name, str, s.Lookup(name).Type()); m != nil {
			fmt.Printf("Found: %s\n", m)
			if err := m.Validate(); err != nil {
				panic(err)
			}

			pkg.Models = append(pkg.Models, m)
			m.CheckedNode = s.Lookup(name).Type().(*types.Named)
			m.Package = p.TypesPkg
		} else {
			pkg.Structs = append(pkg.Structs, name)
		}

	}

	for _, fun := range newFuncs {
		p.tryMatchNewFunc(pkg.Models, fun)
	}
}

func (p *Processor) tryMatchNewFunc(models []*Model, fun *types.Func) {
	modelName := fun.Name()[len("new"):]

	for _, m := range models {
		if m.Name != modelName {
			continue
		}

		sig := fun.Type().(*types.Signature)

		if sig.Recv() != nil {
			continue
		}

		res := sig.Results()
		for i := 0; i < res.Len(); i++ {
			if isTypeOrPtrTo(res.At(i).Type(), m.CheckedNode) {
				m.NewFunc = fun
				return
			}
		}
	}
}

func (p *Processor) tryGetFunction(typ types.Object) *types.Func {
	switch t := typ.(type) {
	case *types.Func:
		return t
	}

	return nil
}

func (p *Processor) tryGetStruct(typ types.Type) *types.Struct {
	switch t := typ.(type) {
	case *types.Named:
		return p.tryGetStruct(t.Underlying())
	case *types.Pointer:
		return p.tryGetStruct(t.Elem())
	case *types.Slice:
		return p.tryGetStruct(t.Elem())
	case *types.Map:
		return p.tryGetStruct(t.Elem())
	case *types.Struct:
		return t
	}

	return nil
}

func (p *Processor) processStruct(name string, s *types.Struct, t types.Type) *Model {
	m := NewModel(name)
	m.New = p.isNewPresent(name)
	m.Init = p.isInitPresent(t)
	m.Events = p.getEvents(name)

	var base int
	if base, m.Fields = p.getFields(s); base == -1 {
		return nil
	}

	p.processBaseField(m, m.Fields[base])
	return m
}

func (p *Processor) getFields(s *types.Struct) (base int, fields []*Field) {
	base, fields = p.processFields(s, []*types.Struct{})
	return
}

func (p *Processor) getEvents(name string) []Event {
	events := []Event{}

	all := []Event{
		BeforeInsert, AfterInsert, BeforeUpdate, AfterUpdate, BeforeSave, AfterSave,
	}

	for _, e := range all {
		if p.isEventPresent(name, e) {
			events = append(events, e)
		}
	}

	return events
}
func (p *Processor) isNewPresent(name string) bool {
	re := regexp.MustCompile(fmt.Sprintf("\\*%sStore\\) New\\(", name))
	for _, code := range p.SourceCode {
		if re.Match(code) {
			return true
		}
	}

	return false
}

func (p *Processor) isEventPresent(name string, e Event) bool {
	re := regexp.MustCompile(fmt.Sprintf("\\*%sStore\\) %s\\(", name, e))

	for _, code := range p.SourceCode {
		if re.Match(code) {
			return true
		}
	}

	return false
}

// Returns which field index is an embedded storable.Document, or -1 if none.
func (p *Processor) processFields(s *types.Struct, done []*types.Struct) (base int, fields []*Field) {
	c := s.NumFields()

	base = -1
	fields = make([]*Field, 0)

	for i := 0; i < c; i++ {
		f := s.Field(i)
		if !f.Exported() {
			continue
		}

		t := reflect.StructTag(s.Tag(i))
		if f.Type().String() == BaseDocument {
			base = i
		}

		field := NewField(f.Name(), f.Type().Underlying().String(), t)
		field.CheckedNode = f
		str := p.tryGetStruct(f.Type())
		if f.Type().String() != BaseDocument && str != nil {
			field.Type = getStructType(f.Type())

			d := false
			for _, v := range done {
				if v == str {
					d = true
					break
				}
			}
			if !d {
				_, subfs := p.processFields(str, append(done, str))
				field.SetFields(subfs)
			}
		}

		fields = append(fields, field)
	}

	return base, fields
}

func (p *Processor) isInitPresent(t types.Type) bool {
	ms := types.NewMethodSet(types.NewPointer(t))
	for i := 0; i < ms.Len(); i++ {
		m := ms.At(i)
		if m.Obj().Name() == "Init" {
			return true
		}
	}

	return false
}

func getStructType(t types.Type) string {
	ts := t.String()
	if ts != "time.Time" && ts != "bson.ObjectId" {
		return "struct"
	}

	return ts
}

func (p *Processor) processBaseField(m *Model, f *Field) {
	m.Collection = f.Tag.Get("collection")
}

func joinDirectory(directory string, files []string) []string {
	r := make([]string, len(files))
	for i, file := range files {
		r[i] = filepath.Join(directory, file)
	}

	return r
}

