func (s *HooksSuite) TestFindHooks(c *C) {
	genPkg := s.fixture(c)

	m := genPkg.Models[0]
	c.Assert(len(m.Hooks), Equals, 2)
	c.Assert(m.Hooks[0], Equals, generator.Hook{
		Before: true,
		Action: generator.InsertHook,
	})
	c.Assert(m.Hooks[1], Equals, generator.Hook{
		Before: true,
		Action: generator.SaveHook,
	})

	c.Assert(len(m.Fields[2].Hooks), Equals, 2)
	c.Assert(m.Fields[2].Hooks[0], Equals, generator.Hook{
		Before: false,
		Action: generator.InsertHook,
	})
	c.Assert(m.Fields[2].Hooks[1], Equals, generator.Hook{
		Before: false,
		Action: generator.SaveHook,
	})

	c.Assert(len(m.Fields[3].Hooks), Equals, 1)
	c.Assert(m.Fields[3].Hooks[0], Equals, generator.Hook{
		Before: true,
		Action: generator.SaveHook,
	})

	c.Assert(len(m.Fields[4].Hooks), Equals, 1)
	c.Assert(m.Fields[4].Hooks[0], Equals, generator.Hook{
		Before: true,
		Action: generator.SaveHook,
	})
}

func (s *HooksSuite) TestGenerateHooks(c *C) {
	genPkg := s.fixture(c)
	td := &generator.TemplateData{genPkg, nil, map[interface{}]string{}}

	got := td.CallHooks("before", "insert", genPkg.Models[0])
	bs, _ := format.Source([]byte("func main() {\n" + got + "\n}"))
	fmt.Println(string(bs))
}

func (s *HooksSuite) fixture(c *C) *generator.Package {
	fixtureSrc := `
	package fixture

	import 	"github.com/tyba/storable"

	type Recur struct {
		storable.Document
		Foo string
		R *Other
		Things map[string][]*Thing
		MoreThings []Thing
	}

	func (r Recur) BeforeInsert() error {
		return nil
	}

	func (r *Recur) BeforeSave() error {
		return nil
	}

	type Other struct {
		R2 *Recur
	}

	func (r Other) AfterInsert() error {
		return nil
	}

	func (r *Other) AfterSave() error {
		return nil
	}

	func (r *Other) BeforeSave() { // Bad signature.
		return nil
	}

	type Thing int

	func (t Thing) BeforeSave() error {
		return nil
	}
	`

	fset := &token.FileSet{}
	astFile, _ := parser.ParseFile(fset, "fixture.go", fixtureSrc, 0)
	cfg := &types.Config{}
	p, _ := cfg.Check("github.com/tcard/navpatch/navpatch", fset, []*ast.File{astFile}, nil)

	prc := generator.NewProcessor("fixture", nil)
	prc.TypesPkg = p
	genPkg, err := prc.ProcessTypesPkg()

	c.Assert(err, IsNil)

	return genPkg
}

package storable

import (
	"strings"

	"gopkg.in/mgo.v2/bson"
)

type Field struct {
	bson string
	typ  string
}

// NewField return a new Field instance.
func NewField(bson, typ string) Field {
	return Field{bson, typ}
}

// Type returns the type of this Field.
func (f Field) Type() string {
	return f.typ
}

// String returns a string with a valid representation to be used on mgo.
func (f Field) String() string {
	return f.bson
}

type Map struct {
	bson string
	typ  string
}

var mapPlaceholder = "[map]"

// NewMap return a new Map instance.
func NewMap(bson, typ string) Map {
	return Map{bson, typ}
}

// Type returns the type used by this Map.
func (f Map) Type() string {
	return f.typ
}

// Key returns a Field for the specific map key.
func (f Map) Key(key string) Field {
	bson := strings.Replace(f.bson, mapPlaceholder, key, -1)
	return NewField(bson, f.typ)
}

var (
	IdField = NewField("_id", "bson.ObjectId")
)

type Dir int

const (
	Asc  Dir = 1
	Desc Dir = -1
)

type Sort []FieldSort

type FieldSort struct {
	F Field
	D Dir
}

// String returns a representation of Sort compatible with the format of mgo.
func (s Sort) String() string {
	var fields []string
	for _, fs := range s {
		f := ""
		if fs.D == Desc {
			f += "-"
		}

		f += fs.F.String()

		fields = append(fields, f)
	}

	return strings.Join(fields, ",")
}

// IsEmpty returns if this sort map is empty or not
func (s Sort) IsEmpty() bool {
	return len(s) == 0
}

type Filter int

const (
	Include Filter = 1
	Exclude Filter = 0
)

type Select []FieldSelect

type FieldSelect struct {
	F Field
	D Filter
}

func (s Select) ToMap() bson.M {
	m := bson.M{}
	for _, fs := range s {
		m[fs.F.String()] = int(fs.D)
	}

	return m
}

// IsEmpty returns if this select is empty or not
func (s Select) IsEmpty() bool {
	return len(s) == 0
}

