type Hook struct {
	Before bool
	Action HookAction
}

func (h Hook) MethodName() string {
	var ret string

	if h.Before {
		ret += "Before"
	} else {
		ret += "After"
	}

	ret += string(h.Action)

	return ret
}

type HookAction string

const (
	InsertHook HookAction = "Insert"
	UpdateHook HookAction = "Update"
	SaveHook   HookAction = "Save"
)

func isTypeOrPtrTo(ptr types.Type, named *types.Named) bool {
	switch ty := ptr.(type) {
	case *types.Pointer:
		if elem, ok := ty.Elem().(*types.Named); ok && elem == named {
			return true
		}
	case *types.Named:
		if ty == named {
			return true
		}
	}
	return false
}

func typeString(ty types.Type, pkg *types.Package) string {
	ret := types.TypeString(ty, types.RelativeTo(pkg))
	parts := strings.Split(ret, "/")
	prefix := ""
	if len(parts) > 1 {
		for _, r := range parts[0] {
			if r == '.' || unicode.IsLetter(r) {
				break
			}
			prefix += string(r)
		}
	}
	return prefix + parts[len(parts)-1]
}

func isPtrToInvalid(ty types.Type) bool {
	ptrTo, ok := ty.(*types.Pointer)
	return ok && ptrTo.Elem() == types.Typ[types.Invalid]
}

type {{.QueryName}} struct {
	storable.BaseQuery
