func (q *{{.QueryName}}) FindById(ids ...bson.ObjectId) *{{.QueryName}} {
	var vs []interface{}
	for _, id := range ids {
		vs = append(vs, id)
	}
	q.AddCriteria(operators.In(storable.IdField, vs...))

	return q
}

