	resultSet, err := s.Store.Find(query)
	if err != nil {
		return nil, err
	}

	return &ProductResultSet{*resultSet}, nil
}

func (s *ProductStore) MustFind(query *ProductQuery) *ProductResultSet {
	resultSet, err := s.Find(query)
	if err != nil {
		panic(err)
	}

	return resultSet
