func (f *Field) GetPath() string {
	recursive := f
	path := make([]string, 0)
	done := map[*Field]bool{}
	for recursive != nil {
		if recursive.isMap {
			path = append(path, "[map]")
		}

		path = append(path, recursive.DbName())
		recursive = recursive.Parent
		if done[recursive] {
			break
		}
		done[recursive] = true
	}

	return strings.Join(reverseSliceStrings(path), ".")
}

