func Test(t *testing.T) { TestingT(t) }

type ProcessorSuite struct{}

var _ = Suite(&ProcessorSuite{})

func (s *ProcessorSuite) TestTags(c *C) {
	fixtureSrc := `
	package fixture

	import 	"github.com/tyba/storable"

	type Foo struct {
		storable.Document
		Int int "foo"
	}
	`

	pkg := s.processFixture(fixtureSrc)
	c.Assert(pkg.Models[0].Fields[1].Tag, Equals, reflect.StructTag("foo"))
}

func (s *ProcessorSuite) TestRecursiveStruct(c *C) {
	fixtureSrc := `
	package fixture

	import 	"github.com/tyba/storable"

	type Recur struct {
		storable.Document
		Foo string
		R *Recur
	}
	`

	pkg := s.processFixture(fixtureSrc)

	c.Assert(
		pkg.Models[0].Fields[2].Fields[2].CheckedNode,
		Equals,
		pkg.Models[0].Fields[2].CheckedNode,
		Commentf("direct type recursivity not handled correctly."),
	)

	c.Assert(len(pkg.Models[0].Fields[2].Fields[2].Fields), Equals, 0)
}

func (s *ProcessorSuite) TestDeepRecursiveStruct(c *C) {
	fixtureSrc := `
	package fixture

	import 	"github.com/tyba/storable"

	type Recur struct {
		storable.Document
		Foo string
		R *Other
	}

	type Other struct {
		R *Recur
	}
	`

	pkg := s.processFixture(fixtureSrc)

	c.Assert(pkg.Models[0].Fields[2].Fields[0].Fields[2].CheckedNode, Equals, pkg.Models[0].Fields[2].CheckedNode, Commentf("direct type recursivity not handled correctly."))
	c.Assert(len(pkg.Models[0].Fields[2].Fields[0].Fields[2].Fields), Equals, 0)
}

func (s *ProcessorSuite) processFixture(source string) *Package {
	fset := &token.FileSet{}
	astFile, err := parser.ParseFile(fset, "fixture.go", source, 0)
	if err != nil {
		panic(err)
	}

	cfg := &types.Config{}
	p, _ := cfg.Check("foo", fset, []*ast.File{astFile}, nil)
	if err != nil {
		panic(err)
	}

	prc := NewProcessor("fixture", nil)
	prc.TypesPkg = p
	pkg, err := prc.processTypesPkg()
	if err != nil {
		panic(err)
	}

	return pkg
}

type {{.ResultSetName}} struct {
    storable.ResultSet
    last    *{{.Name}}
    lastErr error
}

// All returns all documents on the resultset and close the resultset
func (r *{{.ResultSetName}}) All() ([]*{{.Name}}, error) {
    var result []*{{.Name}}
    err := r.ResultSet.All(&result)

    return result, err
}

// One returns the first document on the resultset and close the resultset
func (r *{{.ResultSetName}}) One() (*{{.Name}}, error) {
    var result *{{.Name}}
    err := r.ResultSet.One(&result)

    return result, err
}

// Next prepares the next result document for reading with the Get method.
func (r *{{.ResultSetName}}) Next() (returned bool) {
    r.last = nil
    returned, r.lastErr = r.ResultSet.Next(&r.last)
    return
}

// Get returns the document retrieved with the Next method.
func (r *{{.ResultSetName}}) Get() (*{{.Name}}, error) {
    return r.last, r.lastErr
}

// ForEach iterates the resultset calling to the given function.
func (r *{{.ResultSetName}}) ForEach(f func(*{{.Name}}) error) error {
    for {
        var result *{{.Name}}
        found, err := r.ResultSet.Next(&result)
        if err != nil {
            return err
        }

        if !found {
            break
        }

        err = f(result)
        if err == storable.ErrStop {
            break
        }

        if  err != nil {
            return err
        }
    }

    return nil
}

