package generator

import (
	"fmt"
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"path/filepath"
	"reflect"

	_ "golang.org/x/tools/go/gcimporter"
	"golang.org/x/tools/go/types"
)

const BaseDocument = "github.com/tyba/storable.Document"

type Processor struct {
	Path   string
	Ignore map[string]bool
}

func NewProcessor(path string, ignore []string) *Processor {
	i := make(map[string]bool, 0)
	for _, file := range ignore {
		i[file] = true
	}

	return &Processor{Path: path, Ignore: i}
}

func (p *Processor) Do() (string, []*Model, error) {
	files, err := p.getSourceFiles()
	if err != nil {
		return "", nil, err
	}

	pkg, err := p.parseSourceFiles(files)
	if err != nil {
		fmt.Println(pkg)

		//return "", nil, err
	}

	return pkg.Name(), p.processPackage(pkg), nil
}

func (p *Processor) getSourceFiles() ([]string, error) {
	pkg, err := build.Default.ImportDir(p.Path, 0)
	if err != nil {
		return nil, fmt.Errorf("cannot process directory %s: %s", p.Path, err)
	}

	var files []string
	files = append(files, pkg.GoFiles...)
	files = append(files, pkg.CgoFiles...)

	if len(files) == 0 {
		return nil, fmt.Errorf("%s: no buildable Go files", p.Path)
	}

	return joinDirectory(p.Path, files), nil
}

func (p *Processor) parseSourceFiles(filenames []string) (*types.Package, error) {
	var files []*ast.File
	fs := token.NewFileSet()
	for _, filename := range filenames {
		if _, ok := p.Ignore[filename]; ok {
			continue
		}

		file, err := parser.ParseFile(fs, filename, nil, 0)
		if err != nil {
			return nil, fmt.Errorf("parsing package: %s: %s", filename, err)
		}

		files = append(files, file)
	}

	config := types.Config{FakeImportC: true}
	info := &types.Info{}

	return config.Check(p.Path, fs, files, info)
}

func (p *Processor) processPackage(pkg *types.Package) []*Model {
	s := pkg.Scope()
	r := make([]*Model, 0)
	for _, name := range s.Names() {
		str := p.tryGetStruct(s.Lookup(name).Type())
		if str == nil {
			continue
		}

		if m := p.processStruct(name, str); m != nil {
			r = append(r, m)
		}
	}

	return r
}

func (p *Processor) tryGetStruct(typ types.Type) *types.Struct {
	switch t := typ.(type) {
	case *types.Named:
		return p.tryGetStruct(t.Underlying())
	case *types.Pointer:
		return p.tryGetStruct(t.Elem())
	case *types.Slice:
		return p.tryGetStruct(t.Elem())
	case *types.Map:
		return p.tryGetStruct(t.Elem())
	case *types.Struct:
		return t
	}

	return nil
}

func (p *Processor) processStruct(name string, s *types.Struct) *Model {
	m := NewModel(name)

	var base int
	if base, m.Fields = p.getFields(s); base == -1 {
		return nil
	}

	p.procesBaseField(m, m.Fields[base])
	return m
}

func (p *Processor) getFields(s *types.Struct) (base int, fields []*Field) {
	c := s.NumFields()

	base = -1
	fields = make([]*Field, 0)

	for i := 0; i < c; i++ {
		f := s.Field(i)
		if !f.Exported() {
			continue
		}

		t := reflect.StructTag(s.Tag(i))
		if f.Type().String() == BaseDocument {
			base = i
		}

		field := NewField(f.Name(), f.Type().String(), t)
		str := p.tryGetStruct(f.Type())
		if f.Type().String() != BaseDocument && str != nil {
			_, subfields := p.getFields(str)
			field.SetFields(subfields)
			field.Type = getStructType(f.Type())
		}

		fields = append(fields, field)
	}

	return
}

func getStructType(t types.Type) string {
	ts := t.String()
	if ts != "time.Time" && ts != "bson.ObjectId" {
		return "struct"
	}

	return ts
}

func (p *Processor) procesBaseField(m *Model, f *Field) {
	m.Collection = f.Tag.Get("collection")
}

func joinDirectory(directory string, files []string) []string {
	r := make([]string, len(files))
	for i, file := range files {
		r[i] = filepath.Join(directory, file)
	}

	return r
}

package generator

import (
	"bytes"
	"fmt"
	"go/build"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"text/template"

	"golang.org/x/tools/imports"
)

type Template struct {
	template *template.Template
}

type TemplateData struct {
	*Package
	Fields    []*TemplateField
	Processed map[interface{}]string
}

type TemplateField struct {
	Name   string
	Path   string
	Fields interface{}
}

func (tf *TemplateField) ValidFields() []*Field {
	return tf.Fields.([]*Field)
}

func (t *Template) Execute(wr io.Writer, data *Package) error {
	var buf bytes.Buffer

	td := &TemplateData{data, []*TemplateField{}, map[interface{}]string{}}
	err := t.template.Execute(&buf, td)
	if err != nil {
		return err
	}

	return prettyfy(buf.Bytes(), wr)
}

func (td *TemplateData) GenType(vi interface{}, path string) string {
	v := reflect.ValueOf(vi)
	sv := v
	if v.Kind() == reflect.Ptr {
		sv = v.Elem()
	}
	if sv.FieldByName("Type").Interface().(string) == "struct" {
		if v.MethodByName("ValidFields").IsValid() {
			return td.LinkStruct(path, vi)
		}
		return ""
	} else {
		k := "Field"
		if v.MethodByName("ContainsMap").Call(nil)[0].Interface().(bool) {
			k = "Map"
		}
		return fmt.Sprintf("%v storable.%v", sv.FieldByName("Name"), k)
	}
}

func (td *TemplateData) LinkStruct(path string, vi interface{}) string {
	v := reflect.ValueOf(vi)
	name := v.Elem().FieldByName("Name").Interface().(string)
	schemaName := "schema" + path + name

	if proc, ok := td.Processed[vi]; ok {
		schemaName = proc
		return name + " *" + schemaName
	}
	td.Processed[vi] = schemaName

	td.Fields = append(td.Fields, &TemplateField{
		Name:   schemaName,
		Path:   path + name,
		Fields: v.MethodByName("ValidFields").Call(nil)[0].Interface(),
	})

	return name + " *" + schemaName
}

func (td *TemplateData) GenVar(vi interface{}, done map[interface{}]bool) string {
	if done == nil {
		done = map[interface{}]bool{}
	}

	v := reflect.ValueOf(vi)
	sv := v
	if v.Kind() == reflect.Ptr {
		sv = v.Elem()
	}

	if done[vi] {
		return sv.FieldByName("Name").Interface().(string) + ": nil,"
	}

	if sv.FieldByName("Type").Interface().(string) == "struct" {
		if v.MethodByName("ValidFields").IsValid() {
			return td.StructValue(vi, done)
		}
		return ""
	} else {
		k := "NewField"
		if v.MethodByName("ContainsMap").Call(nil)[0].Interface().(bool) {
			k = "NewMap"
		}

		return fmt.Sprintf(
			`%v: storable.%v("%v", "%v"),`,
			sv.FieldByName("Name"),
			k,
			v.MethodByName("GetPath").Call(nil)[0],
			v.MethodByName("FindableType").Call(nil)[0],
		)
	}
}

func (td *TemplateData) StructValue(vi interface{}, done map[interface{}]bool) string {
	v := reflect.ValueOf(vi)
	name := v.Elem().FieldByName("Name").Interface().(string)

	ifc := v.Interface()
	if done[ifc] {
		return name + ": nil,"
	}
	done[ifc] = true

	ret := name + ": &" + td.Processed[vi] + "{"
	for _, v := range v.MethodByName("ValidFields").Call(nil)[0].Interface().([]*Field) {
		ret += "\n" + td.GenVar(v, done)
	}
	ret += "\n},"

	return ret
}

func prettyfy(input []byte, wr io.Writer) error {
	output, err := imports.Process("storable.go", input, nil)
	if err != nil {
		printDocumentWithNumbers(string(input))
		return err
	}

	_, err = wr.Write(output)
	return err
}

func printDocumentWithNumbers(code string) {
	for i, line := range strings.Split(code, "\n") {
		fmt.Printf("%.3d %s\n", i+1, line)
	}
}

func loadTemplateText(filename string) string {
	filename = filepath.Join(build.Default.GOPATH, "src/github.com/tyba/storable/generator", filename)
	f, err := os.Open(filename)
	if err != nil {
		panic(err)
	}

	buf := bytes.NewBuffer(nil)
	if _, err := buf.ReadFrom(f); err != nil {
		panic(err)
