)

func Test(t *testing.T) { TestingT(t) }

type HooksSuite struct{}

var _ = Suite(&HooksSuite{})

func (s *HooksSuite) TestFindHooks(c *C) {
	genPkg := s.fixture(c)

	m := genPkg.Models[0]
	c.Assert(len(m.Hooks), Equals, 3)
	c.Assert(m.Hooks[0], Equals, generator.Hook{
		Before: true,
		Action: generator.InsertHook,
	})
	c.Assert(m.Hooks[1], Equals, generator.Hook{
		Before: true,
		Action: generator.UpdateHook,
	})
	c.Assert(m.Hooks[2], Equals, generator.Hook{
		Before: true,
		Action: generator.SaveHook,
	})

	c.Assert(len(m.Fields[2].Hooks), Equals, 3)
	c.Assert(m.Fields[2].Hooks[0], Equals, generator.Hook{
		Before: false,
		Action: generator.InsertHook,
	})
	c.Assert(m.Fields[2].Hooks[1], Equals, generator.Hook{
		Before: false,
		Action: generator.UpdateHook,
	})
	c.Assert(m.Fields[2].Hooks[2], Equals, generator.Hook{
		Before: false,
		Action: generator.SaveHook,
	})

	c.Assert(len(m.Fields[3].Hooks), Equals, 1)
	c.Assert(m.Fields[3].Hooks[0], Equals, generator.Hook{
		Before: true,
		Action: generator.SaveHook,
	})
}

func (s *HooksSuite) TestGenerateHooks(c *C) {
	conn, _ := mgo.Dial("localhost")
	db := conn.DB("storable-test")
	defer db.DropDatabase()

	store := hooks.NewRecurStore(db)

	doc := store.New()
	doc.Foo = "Bar"
	doc.R = &hooks.Other{Name: "MyOther", R2: doc}
	failer := &hooks.Failer{}
	doc.MyFailer = failer
	doc.Things = map[string][]*hooks.Thing{
		"foo": nil,
		"bar": {nil, &hooks.Thing{123}},
		"qux": {&hooks.Thing{456}, &hooks.Thing{789}},
	}

	err := store.Insert(doc)
	c.Assert(hooks.Log, DeepEquals, []string{
		"Called BeforeInsert on Recur with Foo Bar",
		"Called BeforeSave on *Recur with Foo Bar",
		"Called BeforeInsert on *Failer",
	})
	c.Assert(err, Not(IsNil))
	herr := err.(storable.HookError)
	c.Assert(herr.Hook, Equals, "BeforeInsert")
	c.Assert(herr.Field, Equals, ".MyFailer")
	c.Assert(herr.Cause.Error(), Equals, "I failed, sorry!")

	hooks.Log = nil
	doc.MyFailer = nil

	err = store.Insert(doc)
	c.Assert(hooks.Log[:2], DeepEquals, []string{
		"Called BeforeInsert on Recur with Foo Bar",
		"Called BeforeSave on *Recur with Foo Bar",
	})
	c.Assert(s.sortedStrs(hooks.Log[2:5]), DeepEquals, s.sortedStrs([]string{
		"Called BeforeSave on Thing 123",
		"Called BeforeSave on Thing 456",
		"Called BeforeSave on Thing 789",
	}))
	c.Assert(hooks.Log[5:], DeepEquals, []string{
		"Called AfterInsert on Other with Name MyOther",
		"Called AfterSave on *Other with Name MyOther",
	})
	c.Assert(err, IsNil)

	hooks.Log = nil
	doc.MyAfterFailer = &hooks.AfterFailer{}

	err = store.Update(doc)
	c.Assert(hooks.Log[:2], DeepEquals, []string{
		"Called BeforeUpdate on *Recur with Foo Bar",
		"Called BeforeSave on *Recur with Foo Bar",
	})
	c.Assert(s.sortedStrs(hooks.Log[2:5]), DeepEquals, s.sortedStrs([]string{
		"Called BeforeSave on Thing 123",
		"Called BeforeSave on Thing 456",
		"Called BeforeSave on Thing 789",
	}))
	c.Assert(hooks.Log[5:], DeepEquals, []string{
		"Called AfterUpdate on Other with Name MyOther",
		"Called AfterSave on *Other with Name MyOther",
		"Called AfterSave on *AfterFailer",
	})
	c.Assert(err, Not(IsNil))
	herr = err.(storable.HookError)
	c.Assert(herr.Hook, Equals, "AfterSave")
	c.Assert(herr.Field, Equals, ".MyAfterFailer")
	c.Assert(herr.Cause.Error(), Equals, "I failed too late, sorry!")

	hooks.Log = nil
	doc.MyAfterFailer = nil

	err = store.Update(doc)
	c.Assert(hooks.Log[:2], DeepEquals, []string{
		"Called BeforeUpdate on *Recur with Foo Bar",
		"Called BeforeSave on *Recur with Foo Bar",
	})
	c.Assert(s.sortedStrs(hooks.Log[2:5]), DeepEquals, s.sortedStrs([]string{
		"Called BeforeSave on Thing 123",
		"Called BeforeSave on Thing 456",
		"Called BeforeSave on Thing 789",
	}))
	c.Assert(hooks.Log[5:], DeepEquals, []string{
		"Called AfterUpdate on Other with Name MyOther",
		"Called AfterSave on *Other with Name MyOther",
	})
	c.Assert(err, IsNil)
}

func (s *HooksSuite) fixture(c *C) *generator.Package {
	_, thisFile, _, _ := func() (uintptr, string, int, bool) { return runtime.Caller(0) }()
	f, _ := os.Open(filepath.Dir(thisFile) + "/fixture.go")

	fset := &token.FileSet{}
	astFile, _ := parser.ParseFile(fset, "fixture.go", f, 0)
	cfg := &types.Config{}
	p, _ := cfg.Check("github.com/tcard/navpatch/navpatch", fset, []*ast.File{astFile}, nil)

	prc := generator.NewProcessor("fixture", nil)
	prc.TypesPkg = p
	genPkg, err := prc.ProcessTypesPkg()

	c.Assert(err, IsNil)

	return genPkg
}

func (s *HooksSuite) sortedStrs(sl []string) []string {
	sort.StringSlice(sl).Sort()
	return sl
}

package storable

import (
	"errors"

	"gopkg.in/mgo.v2"
	"gopkg.in/mgo.v2/bson"
)

var (
	// ErrNonNewDocument non-new documents cannot be inserted
	ErrNonNewDocument = errors.New("Cannot insert a non new document.")
	// ErrNewDocument a new documents cannot be updated
	ErrNewDocument = errors.New("Cannot updated a new document.")
	// ErrEmptyQueryInRaw an empty query cannot be used on any *Raw method
	ErrEmptyQueryInRaw = errors.New("Empty queries are not allowed on raw ops.")
	// ErrEmptyID a document without Id cannot be used with Save method
	ErrEmptyID = errors.New("A document without id is not allowed.")
)

type Store struct {
	db         *mgo.Database
	collection string
}

// NewStore returns a new Store instance
func NewStore(db *mgo.Database, collection string) *Store {
	return &Store{
		db:         db,
		collection: collection,
	}
}

// Insert insert the given document in the collection, returns error if no-new
// document is given. The document id is setted if is empty.
func (s *Store) Insert(doc DocumentBase) error {
	if !doc.IsNew() {
		return ErrNonNewDocument
	}

	if len(doc.GetId()) == 0 {
		doc.SetId(bson.NewObjectId())
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	err := c.Insert(doc)
	if err == nil {
		doc.SetIsNew(false)
	}

	return err
}

// Update update the given document in the collection, returns error if a new
// document is given.
func (s *Store) Update(doc DocumentBase) error {
	if doc.IsNew() {
		return ErrNewDocument
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	return c.UpdateId(doc.GetId(), doc)
}

// Save insert or update the given document in the collection, a document with
// id should be provided. Upsert is used (http://godoc.org/gopkg.in/mgo.v2#Collection.Upsert)
func (s *Store) Save(doc DocumentBase) (updated bool, err error) {
	id := doc.GetId()
	if len(id) == 0 {
		return false, ErrEmptyID
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	inf, err := c.UpsertId(id, doc)
	if err != nil {
		return false, err
	}

	doc.SetIsNew(false)
	return inf.Updated > 0, nil
}

// Delete remove the document from the collection
func (s *Store) Delete(doc DocumentBase) error {
	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	return c.RemoveId(doc.GetId())
}

// Find executes the given query in the collection
func (s *Store) Find(q Query) (*ResultSet, error) {
	sess, c := s.getSessionAndCollection()
	mq := c.Find(q.GetCriteria())

	if !q.GetSort().IsEmpty() {
		mq.Sort(q.GetSort().MgoFormat()...)
	}

	if q.GetSkip() != 0 {
		mq.Skip(q.GetSkip())
	}

	if q.GetLimit() != 0 {
		mq.Limit(q.GetLimit())
	}

	if !q.GetSelect().IsEmpty() {
		mq.Select(q.GetSelect().ToMap())
	}

	return &ResultSet{session: sess, mgoQuery: mq}, nil
}

// RawUpdate performes a direct update in the collection, update is wrapped on
// a $set operator. If a query without criteria is given EmptyQueryInRawErr is
// returned
func (s *Store) RawUpdate(query Query, update interface{}, multi bool) error {
	criteria := query.GetCriteria()
	if len(criteria) == 0 {
		return ErrEmptyQueryInRaw
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	var err error
	if multi {
		_, err = c.UpdateAll(criteria, bson.M{"$set": update})
	} else {
		err = c.Update(criteria, bson.M{"$set": update})
	}

	return err
}

// RawDelete performes a direct remove in the collection. If a query without
// criteria is given EmptyQueryInRawErr is returned
func (s *Store) RawDelete(query Query, multi bool) error {
	criteria := query.GetCriteria()
	if len(criteria) == 0 {
		return ErrEmptyQueryInRaw
	}

	sess, c := s.getSessionAndCollection()
	defer sess.Close()

	var err error
	if multi {
		_, err = c.RemoveAll(criteria)
	} else {
		err = c.Remove(criteria)
	}

	return err
}

func (s *Store) getSessionAndCollection() (*mgo.Session, *mgo.Collection) {
	sess := s.db.Session.Clone()

	return sess, sess.DB(s.db.Name).C(s.collection)
}

package operators

import (
	"gopkg.in/mgo.v2/bson"
)

// Or Joins query clauses with a logical OR returns all documents that match
// the conditions of either clause.
func Or(clauses ...bson.M) bson.M {
	return bson.M{"$or": clauses}
}

// And Joins query clauses with a logical AND returns all documents that match
// the conditions of both clauses.
func And(clauses ...bson.M) bson.M {
	return bson.M{"$and": clauses}
}

// Not Inverts the effect of a query expression and returns documents that do
// not match the query expression.
func Not(expr bson.M) bson.M {
	result := make(bson.M, 0)
	for key, e := range expr {
		result[key] = bson.M{"$not": e}
	}

	return result
}

// Nor Joins query clauses with a logical NOR returns all documents that fail
// to match both clauses.
func Nor(clauses ...bson.M) bson.M {
	return bson.M{"$nor": clauses}
}

