package model

import (
	"fmt"
	"reflect"
	"strings"
)

var findableTypes = map[string]bool{
	"string":  true,
	"int":     true,
	"int8":    true,
	"int16":   true,
	"int32":   true,
	"int64":   true,
	"uint":    true,
	"uint8":   true,
	"uint16":  true,
	"uint32":  true,
	"uint64":  true,
	"float32": true,
	"float64": true,
}

type Model struct {
	Name       string
	Collection string
	Fields     []*Field
}

func NewModel(name string) *Model {
	return &Model{
		Name:   name,
		Fields: make([]*Field, 0),
	}
}

func (m *Model) String() string {
	fields := make([]string, 0)
	for _, f := range m.Fields {
		fields = append(fields, f.String())
	}

	fieldsStr := strings.Join(fields, ", ")
	str := fmt.Sprintf("(Model '%s' [ %s ]", m.Name, fieldsStr)

	return str
}

func (m *Model) FindableFields() []*Field {
	fields := make([]*Field, 0)
	for _, f := range m.Fields {
		if f.Findable() {
			fields = append(fields, f)
		}
	}

	return fields
}

type Field struct {
	Name string
	Type string
	Tag  *reflect.StructTag
}

func (f *Field) String() string {
	return fmt.Sprintf("%s %s %s", f.Name, f.Type, f.Tag)
}
func (f *Field) GetTagValue(key string) string {
	if f.Tag == nil {
		return ""
	}
	return f.Tag.Get(key)
}

func (f *Field) DbName() string {
	name := f.GetTagValue("bson")
	endFieldName := strings.Index(name, ",")
	if endFieldName != -1 {
		name = name[:endFieldName]
	}

	if name == "" {
		name = strings.ToLower(f.Name)
	}

	return name
}

func (f *Field) Findable() bool {
	t := strings.Replace(f.Type, "[]", "", 1)
	return findableTypes[t]
}

package storable

import (
	"errors"

	"gopkg.in/mgo.v2"
	"gopkg.in/mgo.v2/bson"
)

var (
	NonNewDocumentErr  = errors.New("Cannot insert a non new document.")
	NewDocumentErr     = errors.New("Cannot updated a new document.")
	EmptyQueryInRawErr = errors.New("Empty queries are not allowed on raw ops.")
)

type Store struct {
	Collection string

	collection *mgo.Collection
}

func NewStore(db *mgo.Database, collection string) *Store {
	return &Store{
		Collection: collection,
		collection: db.C(collection),
	}
}

func (s *Store) Insert(doc DocumentBase) error {
	if !doc.IsNew() {
		return NonNewDocumentErr
	}

	doc.SetId(bson.NewObjectId())
	err := s.collection.Insert(doc)
	if err == nil {
		doc.SetIsNew(false)
	}

	return err
}

func (s *Store) Update(doc DocumentBase) error {
	if doc.IsNew() {
		return NewDocumentErr
	}

	return s.collection.Update(bson.M{"_id": doc.GetId()}, doc)
}

func (s *Store) Delete(doc DocumentBase) error {
	return s.collection.Remove(bson.M{"_id": doc.GetId()})
}

func (s *Store) Find(q Query) (*ResultSet, error) {
	mq := s.collection.Find(q.GetCriteria())

	if !q.GetSort().IsEmpty() {
		mq.Sort(q.GetSort().String())
	}

	if q.GetSkip() != 0 {
		mq.Skip(q.GetSkip())
	}

	if q.GetLimit() != 0 {
		mq.Limit(q.GetLimit())
	}

	return &ResultSet{mgoQuery: mq}, nil
}

func (s *Store) RawUpdate(query Query, update interface{}) error {
	criteria := query.GetCriteria()
	if len(criteria) == 0 {
		return EmptyQueryInRawErr
	}

	return s.collection.Update(criteria, update)
}

