// Mod Performs a modulo operation on the value of a field and selects documents
// with a specified result.
func Mod(field Field, divisor, remainder float64) bson.M {
	return bson.M{field.String(): bson.M{"$mod": []float64{divisor, remainder}}}
}

// RegEx Selects documents where values match a specified regular expression.
func RegEx(field Field, regexp, options string) bson.M {
	return bson.M{field.String(): bson.M{"$regex": bson.RegEx{regexp, options}}}
}

// Text performs a text search on the content of the fields indexed with a text
// index.
func Text(field Field, search, lang string) bson.M {
	return bson.M{
		field.String(): bson.M{
			"$text": bson.M{"$search": search, "$language": lang},
		},
	}
}

// Where Matches documents that satisfy a JavaScript expression.
func Where(field Field, code string, scope interface{}) bson.M {
	return bson.M{
		field.String(): bson.M{
			"$where": bson.JavaScript{Code: code, Scope: scope},
		},
	}
}

package storable

import (
	"errors"

	"gopkg.in/mgo.v2"
)

var (
	ResultSetClosed = errors.New("Cannot close a closed resultset.")
)

type ResultSet struct {
	IsClosed bool
	mgoQuery *mgo.Query
	mgoIter  *mgo.Iter
}

func (r *ResultSet) Count() (int, error) {
	return r.mgoQuery.Count()
}

func (r *ResultSet) All(result interface{}) error {
	defer r.Close()
	return r.mgoQuery.All(result)
}

func (r *ResultSet) One(doc interface{}) (bool, error) {
	defer r.Close()
	return r.Next(doc)
}

func (r *ResultSet) Next(doc interface{}) (bool, error) {
	if r.mgoIter == nil {
		r.mgoIter = r.mgoQuery.Iter()
	}

	returned := r.mgoIter.Next(doc)
	if base, ok := doc.(DocumentBase); ok && returned {
		base.SetIsNew(false)
	}

	return returned, r.mgoIter.Err()
}

func (r *ResultSet) Close() error {
	if r.IsClosed {
		return ResultSetClosed
	}

	r.IsClosed = true
	if r.mgoIter == nil {
		return nil
	}

	return r.mgoIter.Close()
}

