func (s *{{.StoreName}}) Save(doc *{{.Name}}) (updated bool, err error) {
		{{if or (.Events.Has "BeforeUpdate") (.Events.Has "BeforeInsert")}} \
		switch doc.IsNew() {
		{{if .Events.Has "BeforeInsert"}} \
				case true:
						if err := s.BeforeInsert(doc); err != nil {
