func (s *ProcessorSuite) TestRecursiveStruct(c *C) {
	fixtureSrc := `
	package fixture

	import 	"gopkg.in/src-d/storable.v1"

	type Recur struct {
		storable.Document
		Foo string
		R *Recur
	}
	`

	pkg := s.processFixture(fixtureSrc)

	c.Assert(
		pkg.Models[0].Fields[2].Fields[2].CheckedNode,
		Equals,
