		}
	}
	if doc.R != nil {
		// Loop: .R.R2.R2 *..Recur

	}
	for k0, _ := range doc.MoreThings {
		if err := doc.MoreThings[k0].BeforeSave(); err != nil {
			return updated, storable.HookError{
				Hook:  "BeforeSave",
				Field: ".MoreThings[k0]",
				Cause: err,
