				return updated, storable.HookError{
					Hook:  "AfterSave",
					Field: ".MyAfterFailer",
					Cause: err,
				}
			}

		}

	} else {
		if doc.R != nil {
			if err := doc.R.AfterInsert(); err != nil {
				return updated, storable.HookError{
					Hook:  "AfterInsert",
					Field: ".R",
					Cause: err,
