	if err := doc.BeforeInsert(); err != nil {
		return storable.HookError{
			Hook:  "BeforeInsert",
			Field: "doc",
			Cause: err,
		}
	}
	if err := doc.BeforeSave(); err != nil {
		return storable.HookError{
			Hook:  "BeforeSave",
			Field: "doc",
			Cause: err,
		}
